def first_index(values, target):
    for index in range(len(values)):
        if values[index] == target:
            return index
    return -1

print(first_index([4, 2, 4], 4))
print(first_index([4, 2, 4], 9))
print(first_index([], 4))

def first_index(values, target):
    for index in range(len(values)):
        if values[index] == target:
            return index
    return -1

values = [10, 20]
for target in [10, 7]:
    result = first_index(values, target)
    if result != -1:
        print(result, values[result])
    else:
        print("없음")
